#!/usr/bin/env python3
"""Offline acceptance tests for both cleanup scripts; no account calls are made.

Run with ../.venv/bin/python test_cleanup_safety.py, or from the workspace root:
v2/.venv/bin/python v2/tests/test_cleanup_safety.py

Failures identify unmet cleanup requirements. The Python entry point uses an in-memory API double. The shell entry point
uses a local HTTP server; neither can access an E2B account.
"""

import contextlib
import io
import json
import os
from pathlib import Path
import runpy
import subprocess
import sys
import tempfile
from types import SimpleNamespace
import unittest
from unittest.mock import patch
from datetime import datetime, timedelta, timezone

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "cleanup"))


def sandbox(sid, paused_days=100, started_days=120, state="paused"):
    now = datetime.now(timezone.utc)
    return dict(sandboxId=sid, state=state, metadata={"env": "test"},
                startedAt=(now - timedelta(days=started_days)).isoformat().replace("+00:00", "Z"),
                endAt=(now - timedelta(days=paused_days)).isoformat().replace("+00:00", "Z"))


class Backend:
    def __init__(self, config):
        self.config = config
        self.calls = []
        self.snapshot_lists = {}

    def call(self, operation, sid=None):
        self.calls.append([operation, sid])
        cfg = self.config
        if operation == "list":
            if cfg.get("list_fail"):
                raise RuntimeError("503 listing unavailable")
            return sorted(cfg.get("sandboxes", []), key=lambda s: s["startedAt"])
        if operation == "info":
            if sid in cfg.get("info_fail", []):
                raise RuntimeError("503 service unavailable")
            if sid in cfg.get("network_fail", []):
                raise ConnectionError("connection reset")
            if sid in cfg.get("gone", []):
                raise KeyError(sid)
            item = next((s for s in cfg["sandboxes"] if s["sandboxId"] == sid), None)
            if item is None:
                raise KeyError(sid)
            sequence = cfg.get("info_sequence", {}).get(sid)
            return sequence.pop(0) if sequence else cfg.get("current", {}).get(sid, item)
        if operation == "snapshots":
            count = self.snapshot_lists.get(sid, 0) + 1
            self.snapshot_lists[sid] = count
            if count == cfg.get("snapshot_list_fail", {}).get(sid):
                raise RuntimeError("503 snapshot listing unavailable")
            return cfg.get("snapshots", {}).get(sid, [])
        if operation == "kill":
            if sid in cfg.get("kill_fail", []):
                raise RuntimeError("503 kill failed")
            if sid in cfg.get("gone_at_kill", []):
                return False
            if sid in cfg.get("resume_at_kill", []):
                self.calls.append(["killed_running_sandbox", sid])
            cfg["sandboxes"] = [s for s in cfg["sandboxes"] if s["sandboxId"] != sid]
            if sid in cfg.get("lost_kill_response", []):
                raise ConnectionError("kill response lost")
            return True
        if operation == "delete_snapshot":
            if sid in cfg.get("snapshot_delete_fail", []):
                raise RuntimeError("503 snapshot delete failed")
            for ids in cfg.get("snapshots", {}).values():
                if sid in ids:
                    ids.remove(sid)
                    return True
            return False
        raise AssertionError(operation)


class FakeAPI:
    def __init__(self, state):
        self.state = state

    def list_paused(self, metadata=None):
        from sandbox_backend import normalize
        for item in self.state.call('list'):
            yield normalize(item)

    def call(self, op, sid):
        from sandbox_backend import BackendError, Missing
        try:
            return self.state.call(op, sid)
        except KeyError as error:
            raise Missing('not found') from error
        except (RuntimeError, ConnectionError) as error:
            raise BackendError(str(error)) from error

    def get_info(self, sid):
        from sandbox_backend import normalize
        return normalize(self.call('info', sid))

    def kill(self, sid):
        return self.call('kill', sid)

    def snapshots(self, sid):
        return list(self.call('snapshots', sid))

    def delete_snapshot(self, sid):
        return self.call('delete_snapshot', sid)

    def close(self):
        pass

    def cancel(self):
        pass


def run_python(backend, args):
    args = test_args(backend, args)
    stdout, stderr = io.StringIO(), io.StringIO()
    rc = 0
    from sandbox_backend import backend as real_backend

    def factory(name, **kwargs):
        if os.environ.get('E2B_DEBUG', '').lower() == 'true':
            return real_backend(name, **kwargs)
        return FakeAPI(backend)

    with patch.dict(os.environ, {"E2B_API_KEY": "[REDACTED]"}), \
            patch('sandbox_backend.backend', factory), \
            patch.object(sys, 'argv', ['cleanup'] + args), \
            contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
        try:
            runpy.run_path(str(ROOT / 'cleanup' / 'cleanup_paused_sandboxes.py'), run_name='__main__')
        except SystemExit as error:
            rc = error.code
    return SimpleNamespace(returncode=rc, stdout=stdout.getvalue(), stderr=stderr.getvalue())


def run_shell(backend, args):
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
    from urllib.parse import parse_qs, unquote, urlparse
    import threading
    args = test_args(backend, args)
    mutex = threading.Lock()

    class Handler(BaseHTTPRequestHandler):
        def log_message(self, *_):
            pass

        def do_GET(self):
            self.handle_request()

        def do_DELETE(self):
            self.handle_request()

        def handle_request(self):
            query = parse_qs(urlparse(self.path).query)
            path = urlparse(self.path).path
            status, headers, data = 200, {}, None
            with mutex:
                try:
                    if path == '/v2/sandboxes':
                        items = backend.call('list')
                        # Cursor uses an ID, so deleting previous pages cannot shift it.
                        ids = sorted(items, key=lambda s: (s['startedAt'], s['sandboxId']))
                        token = query.get('nextToken', [None])[0]
                        if token:
                            ids = [s for s in ids if s['startedAt'] > token]
                        limit = int(query['limit'][0])
                        data = ids[:limit]
                        if len(ids) > limit:
                            headers['X-Next-Token'] = data[-1]['startedAt']
                    elif path == '/snapshots':
                        items = backend.call('snapshots', query['sandboxID'][0])
                        offset = int(query.get('nextToken', ['0'])[0])
                        limit = int(query['limit'][0])
                        data = [{'snapshotID': sid} for sid in items[offset:offset + limit]]
                        if offset + limit < len(items):
                            headers['X-Next-Token'] = str(offset + limit)
                    elif path.startswith('/sandboxes/'):
                        sid = path.rsplit('/', 1)[1]
                        if self.command == 'GET':
                            data = backend.call('info', sid)
                        else:
                            status = 204 if backend.call('kill', sid) else 404
                    elif path.startswith('/templates/'):
                        status = 204 if backend.call('delete_snapshot', unquote(path.rsplit('/', 1)[1])) else 404
                    else:
                        status = 404
                except KeyError:
                    status = 404
                except (RuntimeError, ConnectionError):
                    status = 503
            self.send_response(status)
            for key, value in headers.items():
                self.send_header(key, value)
            self.end_headers()
            if data is not None:
                self.wfile.write(json.dumps(data).encode())

    server = ThreadingHTTPServer(('127.0.0.1', getattr(backend, 'port', 0)), Handler)
    backend.port = server.server_port
    thread = threading.Thread(target=lambda: server.serve_forever(poll_interval=0.01), daemon=True)
    thread.start()
    try:
        env = {k: v for k, v in os.environ.items() if not k.startswith('E2B_')}
        env.update(E2B_API_KEY='[REDACTED]', E2B_API_URL=f'http://127.0.0.1:{server.server_port}',
                   E2B_TOOLS_PYTHON=sys.executable)
        return subprocess.run(['bash', str(ROOT / 'cleanup' / 'cleanup_paused_sandboxes_cli.sh'),
                               *args, '--rate', '10000', '--retries', '0'],
                              capture_output=True, text=True, env=env, timeout=30)
    finally:
        server.shutdown()
        server.server_close()
        thread.join()


def test_args(backend, args):
    args = list(args)
    if not hasattr(backend, "journal_temp"):
        backend.journal_temp = tempfile.TemporaryDirectory()
    args += ["--journal", str(Path(backend.journal_temp.name) / "journal.json")]
    if "--apply" in args and not backend.config.get("omit_recheck"):
        args += ["--recheck"]
    return args


class CleanupSafety(unittest.TestCase):
    def each(self, config, args, assertion):
        for name, runner in [("python", run_python), ("shell", run_shell)]:
            with self.subTest(script=name):
                backend = Backend(json.loads(json.dumps(config)))
                proc = runner(backend, args)
                try:
                    assertion(backend, proc)
                finally:
                    backend.journal_temp.cleanup()

    def test_dry_run_selects_pause_age_and_never_mutates(self):
        def verify(b, p):
            self.assertEqual(p.returncode, 0, p.stderr)
            self.assertIn("old\t", p.stdout)
            self.assertNotIn("recent-pause\t", p.stdout)
            self.assertNotIn("running\t", p.stdout)
            self.assertFalse(any(c[0] in ("kill", "delete_snapshot") for c in b.calls))
        self.each(dict(sandboxes=[sandbox("old"), sandbox("recent-pause", 1),
                                  sandbox("running", state="running")]), [], verify)

    def test_started_age_mode(self):
        self.each(dict(sandboxes=[sandbox("old-start-recent-pause", 1)]), ["--age-from", "started"],
                  lambda b, p: self.assertIn("old-start-recent-pause\t", p.stdout))

    def test_more_than_one_thousand_candidates(self):
        self.each(dict(sandboxes=[sandbox(f"s{i}") for i in range(1001)]), [],
                  lambda b, p: self.assertEqual(sum("\tstarted=" in s for s in p.stdout.splitlines()), 1001))

    def test_apply_deletes_sandbox_and_snapshots(self):
        def verify(b, p):
            self.assertEqual(p.returncode, 0, p.stderr)
            self.assertEqual(b.config["sandboxes"], [])
            self.assertEqual(b.config["snapshots"]["old"], [])
        self.each(dict(sandboxes=[sandbox("old")], snapshots={"old": ["snap"]}),
                  ["--apply", "--delete-snapshots"], verify)

    def test_snapshot_pagination_in_dry_run(self):
        def verify(b, p):
            self.assertEqual(p.returncode, 0, p.stderr)
            self.assertEqual(sum(s.startswith("  named snapshot ") for s in p.stdout.splitlines()), 101)
            self.assertFalse(any(c[0] in ("kill", "delete_snapshot") for c in b.calls))
        self.each(dict(sandboxes=[sandbox("old")], snapshots={"old": [f"snap{i}" for i in range(101)]}),
                  ["--delete-snapshots"], verify)

    def test_recheck_skips_resumed_and_disappeared_candidates(self):
        self.each(dict(sandboxes=[sandbox("resumed"), sandbox("gone")], gone=["gone"],
                       current={"resumed": sandbox("resumed", state="running")}), ["--apply"],
                  lambda b, p: self.assertFalse(any(c[0] == "kill" for c in b.calls)))

    def test_kill_failure_continues_and_exits_nonzero(self):
        def verify(b, p):
            self.assertNotEqual(p.returncode, 0)
            self.assertIn(["kill", "second"], b.calls)
        self.each(dict(sandboxes=[sandbox("first"), sandbox("second")], kill_fail=["first"]),
                  ["--apply"], verify)

    def test_lookup_service_failure_is_not_success(self):
        self.each(dict(sandboxes=[sandbox("old")], info_fail=["old"]), ["--apply"],
                  lambda b, p: self.assertNotEqual(p.returncode, 0, p.stdout))

    def test_network_failure_does_not_abort_remaining_sandboxes(self):
        self.each(dict(sandboxes=[sandbox("first"), sandbox("second")], network_fail=["first"]),
                  ["--apply"], lambda b, p: self.assertIn(["kill", "second"], b.calls, p.stderr))

    def test_snapshot_preview_failure_does_not_abort_other_candidates(self):
        def verify(b, p):
            self.assertEqual(p.returncode, 1)
            self.assertIn(["snapshots", "second"], b.calls)
            self.assertFalse(any(c[0] in ("kill", "delete_snapshot") for c in b.calls))
        self.each(dict(sandboxes=[sandbox("first"), sandbox("second")],
                       snapshot_list_fail={"first": 1}), ["--delete-snapshots"], verify)

    def test_snapshot_listing_apply_failure_does_not_abort_other_candidates(self):
        self.each(dict(sandboxes=[sandbox("first"), sandbox("second")],
                       snapshot_list_fail={"first": 1}), ["--apply", "--delete-snapshots"],
                  lambda b, p: self.assertIn(["kill", "second"], b.calls, p.stderr))

    def test_snapshot_delete_failure_still_attempts_remaining_snapshots(self):
        self.each(dict(sandboxes=[sandbox("old")], snapshots={"old": ["bad", "good"]},
                       snapshot_delete_fail=["bad"]), ["--apply", "--delete-snapshots"],
                  lambda b, p: self.assertIn(["delete_snapshot", "good"], b.calls, p.stderr))

    def test_rerun_recovers_snapshot_after_partial_failure(self):
        for name, runner in [("python", run_python), ("shell", run_shell)]:
            with self.subTest(script=name):
                b = Backend(dict(sandboxes=[sandbox("old")], snapshots={"old": ["snap"]},
                                 snapshot_delete_fail=["snap"]))
                self.assertNotEqual(runner(b, ["--apply", "--delete-snapshots"]).returncode, 0)
                self.addCleanup(b.journal_temp.cleanup)
                b.config["snapshot_delete_fail"] = []
                p = runner(b, ["--apply", "--delete-snapshots"])
                self.assertEqual(b.config["snapshots"]["old"], [], p.stdout)
                self.assertEqual(p.returncode, 0, p.stderr)

    def test_lost_kill_response_recovers_without_listing(self):
        for name, runner in [("python", run_python), ("shell", run_shell)]:
            with self.subTest(script=name):
                b = Backend(dict(sandboxes=[sandbox("old")], snapshots={"old": ["snap"]},
                                 lost_kill_response=["old"]))
                first = runner(b, ["--apply", "--delete-snapshots"])
                self.addCleanup(b.journal_temp.cleanup)
                self.assertEqual(first.returncode, 1, first.stderr)
                self.assertEqual(b.config["sandboxes"], [])
                self.assertEqual(b.config["snapshots"]["old"], ["snap"])
                b.config["list_fail"] = True
                p = runner(b, ["--apply", "--delete-snapshots", "--retry-pending"])
                self.assertEqual(p.returncode, 0, p.stderr)
                self.assertEqual(b.config["snapshots"]["old"], [])
                data = json.loads((Path(b.journal_temp.name) / "journal.json").read_text())
                self.assertEqual(data["pending"], {})

    def test_recheck_after_snapshot_listing_skips_changed_parent(self):
        old = sandbox("old")
        def verify(b, p):
            self.assertEqual(p.returncode, 0, p.stderr)
            self.assertFalse(any(c[0] in ("kill", "delete_snapshot") for c in b.calls))
            self.assertEqual(json.loads((Path(b.journal_temp.name) / "journal.json").read_text())["pending"], {})
        self.each(dict(sandboxes=[old], snapshots={"old": ["snap"]},
                       info_sequence={"old": [old, sandbox("old", state="running")]}),
                  ["--apply", "--delete-snapshots"], verify)

    def test_changed_metadata_is_rechecked(self):
        changed = sandbox("old")
        changed["metadata"] = {"env": "prod"}
        self.each(dict(sandboxes=[sandbox("old")], current={"old": changed}),
                  ["--metadata", "env=test", "--apply"],
                  lambda b, p: self.assertFalse(any(c[0] == "kill" for c in b.calls)))

    def test_dry_run_does_not_write_journal(self):
        def verify(b, p):
            self.assertEqual(p.returncode, 0, p.stderr)
            self.assertEqual(list(Path(b.journal_temp.name).iterdir()), [])
        self.each(dict(sandboxes=[sandbox("old")], snapshots={"old": ["snap"]}),
                  ["--delete-snapshots"], verify)

    def test_invalid_days_fail_before_account_access(self):
        for value in ("-1", "nan", "inf", "garbage"):
            self.each(dict(sandboxes=[]), ["--days", value],
                      lambda b, p: (self.assertEqual(p.returncode, 2), self.assertFalse(b.calls)))

    def test_journal_write_failure_prevents_kill(self):
        from cleanup_journal import Journal
        b = Backend(dict(sandboxes=[sandbox("old")], snapshots={"old": ["snap"]}))
        with patch.object(Journal, "save", side_effect=OSError("disk full")):
            p = run_python(b, ["--apply", "--delete-snapshots"])
        self.addCleanup(b.journal_temp.cleanup)
        self.assertEqual(p.returncode, 1)
        self.assertIn("disk full", p.stderr)
        self.assertFalse(any(c[0] in ("kill", "delete_snapshot") for c in b.calls))

    def test_sdk_debug_mode_rejected_before_account_access(self):
        b = Backend(dict(sandboxes=[sandbox("old")], snapshots={"old": ["snap"]}))
        with patch.dict(os.environ, E2B_DEBUG="true"):
            result = run_python(b, ["--apply", "--delete-snapshots"])
        self.addCleanup(b.journal_temp.cleanup)
        self.assertEqual(result.returncode, 1, result.stdout)
        self.assertIn('E2B_DEBUG', result.stderr)
        self.assertFalse(b.calls)

    def test_apply_without_resume_assertion_uses_listed_state(self):
        def verify(b, p):
            self.assertEqual(p.returncode, 0, p.stderr)
            self.assertIn(['kill', 'old'], b.calls)
            self.assertFalse(any(op == 'info' for op, _ in b.calls))
        self.each(dict(sandboxes=[sandbox('old')], omit_recheck=True), ['--apply'], verify)


if __name__ == "__main__":
    unittest.main(verbosity=2)

"""Shared pacing and bounded retries for every cleanup HTTP attempt."""
import math
import random
import threading
import time
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime

import httpx


class BackendError(RuntimeError):
    pass


class Missing(BackendError):
    pass


class AuthorizationError(BackendError):
    pass


class RetryLaterError(BackendError):
    pass


def retry_after(value):
    if not value:
        return None
    try:
        seconds = float(value)
        if math.isfinite(seconds) and seconds >= 0:
            return seconds
    except ValueError:
        pass
    try:
        when = parsedate_to_datetime(value)
        if when.tzinfo is None:
            return None
        return max(0, (when - datetime.now(timezone.utc)).total_seconds())
    except (TypeError, ValueError, OverflowError):
        return None


class RequestControl:
    def __init__(self, rate=20, retries=5, clock=time.monotonic, sleep=None):
        self.interval = 1 / rate
        self.retries = retries
        self.clock = clock
        self.lock = threading.Lock()
        self.next_request = 0.0
        self.cancelled = threading.Event()
        self.sleep = sleep or self.cancelled.wait
        self.attempts = 0
        self.retried = 0

    def wait(self):
        while True:
            with self.lock:
                if self.cancelled.is_set():
                    raise BackendError('cleanup stopped')
                delay = self.next_request - self.clock()
                if delay <= 0:
                    self.next_request = self.clock() + self.interval
                    self.attempts += 1
                    return
            # Recheck after waking: another worker or Retry-After can move the slot.
            self.sleep(delay)

    def defer(self, delay):
        with self.lock:
            self.next_request = max(self.next_request, self.clock() + delay)
            self.retried += 1

    def request(self, client, method, path, **kwargs):
        for attempt in range(self.retries + 1):
            self.wait()
            try:
                response = client.request(method, path, **kwargs)
            except httpx.TransportError:
                if attempt == self.retries:
                    raise BackendError(f'{method} {path}: transport failure after {attempt + 1} attempts') from None
                self.defer(min(30, 2 ** attempt) + random.uniform(0, 0.25))
                continue
            if response.status_code in (401, 403):
                self.cancelled.set()
                raise AuthorizationError(f'{method} {path}: HTTP {response.status_code}; check API key and region')
            if response.status_code == 404:
                raise Missing(f'{method} {path}: not found')
            if response.status_code in (429, 500, 502, 503, 504):
                delay = retry_after(response.headers.get('Retry-After'))
                if delay is not None and delay > 60:
                    self.cancelled.set()
                    raise RetryLaterError(f'{method} {path}: Retry-After exceeds 60s; retry in a later run')
                self.defer(delay if delay is not None else min(30, 2 ** attempt) + random.uniform(0, 0.25))
                if attempt < self.retries:
                    response.close()
                    continue
            if response.status_code >= 300:
                raise BackendError(f'{method} {path}: HTTP {response.status_code} after {attempt + 1} attempts')
            return response
        raise AssertionError('unreachable')

"""Locked, atomic recovery state for explicitly selected named snapshot cleanup."""
import fcntl
import hashlib
import json
import os
from pathlib import Path
import tempfile
from contextlib import contextmanager
from sandbox_backend import identifier, snapshot_identifier, timestamp


@contextmanager
def run_lock(path=None, enabled=True):
    if not enabled:
        yield
        return
    endpoint = os.environ.get('E2B_API_URL') or f"https://api.{os.environ.get('E2B_DOMAIN') or 'e2b.app'}"
    identity = json.dumps([os.environ.get('E2B_API_KEY'), endpoint.rstrip('/')])
    suffix = hashlib.sha256(identity.encode()).hexdigest()[:20]
    path = Path(path) if path else Path(tempfile.gettempdir()) / f'e2b-cleanup-{os.getuid()}-{suffix}.lock'
    with path.open('a') as lock:
        os.chmod(path, 0o600)
        try:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise ValueError('another cleanup is running with these credentials and endpoint') from None
        yield


class Journal:
    def __init__(self, path, scope, writable):
        # Equivalent numeric CLI arguments must select the same recovery file.
        scope = {**scope, 'days': float(scope['days']) if scope['days'] else 0.0}
        key = os.environ.get('E2B_API_KEY')
        if not key:
            raise ValueError('E2B_API_KEY is required for named snapshot recovery, including the CLI backend')
        domain = os.environ.get('E2B_DOMAIN') or 'e2b.app'
        endpoint = (os.environ.get('E2B_API_URL') or f'https://api.{domain}').rstrip('/')
        identity = json.dumps([key, endpoint])
        self.identity = hashlib.sha256(identity.encode()).hexdigest()
        self.scope = scope
        suffix = hashlib.sha256(json.dumps([self.identity, scope], sort_keys=True).encode()).hexdigest()[:20]
        self.path = Path(path) if path else Path(__file__).with_name(f'.cleanup-journal-{suffix}.json')
        self.writable, self.lock = writable, None
        self.data = {'schema_version': 1, 'identity': self.identity, 'scope': scope, 'pending': {}}

    def __enter__(self):
        if self.writable:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            self.lock = open(str(self.path) + '.lock', 'a')
            os.chmod(self.lock.name, 0o600)
            try:
                fcntl.flock(self.lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError:
                self.lock.close()
                raise ValueError('another cleanup is using this journal') from None
        try:
            if self.path.exists():
                data = json.loads(self.path.read_text())
                if not isinstance(data, dict):
                    raise ValueError('invalid recovery journal')
                if data.get('schema_version') != 1 or data.get('identity') != self.identity or data.get('scope') != self.scope:
                    raise ValueError('journal belongs to different credentials, endpoint, or selection; use the original options or a different --journal')
                if not isinstance(data.get('pending'), dict):
                    raise ValueError('invalid recovery journal')
                for sid, record in data['pending'].items():
                    identifier(sid)
                    if not isinstance(record, dict):
                        raise ValueError('invalid pending journal entry')
                    if record['status'] not in ('prepared', 'sandbox_deleted') or not isinstance(record['snapshots'], list):
                        raise ValueError('invalid pending journal entry')
                    timestamp(record['started_at']); timestamp(record['paused_at'])
                    for snapshot in record['snapshots']:
                        snapshot_identifier(snapshot)
                self.data = data
            return self
        except BaseException:
            self.__exit__(None, None, None)
            raise

    @property
    def pending(self):
        return self.data['pending']

    def save(self):
        if not self.writable:
            raise ValueError('cannot write a dry-run journal')
        fd, temp = tempfile.mkstemp(prefix=self.path.name + '.', dir=self.path.parent)
        try:
            with os.fdopen(fd, 'w') as handle:
                json.dump(self.data, handle, indent=2, sort_keys=True)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temp, self.path)
            dir_fd = os.open(self.path.parent, os.O_RDONLY)
            try:
                os.fsync(dir_fd)
            finally:
                os.close(dir_fd)
        finally:
            if os.path.exists(temp):
                os.unlink(temp)

    def __exit__(self, *_):
        if self.lock is not None:
            self.lock.close()

"""Streaming cleanup API operations, shared by Python and shell entry points."""
import argparse
from datetime import datetime, timezone
import math
import os
import re
import sys
from types import SimpleNamespace
from urllib.parse import quote, urlencode, urlparse

import httpx

from request_control import AuthorizationError, BackendError, Missing, RequestControl, RetryLaterError


def timestamp(value):
    if not isinstance(value, (str, datetime)):
        raise ValueError('timestamps must be ISO strings or datetime values')
    result = value if isinstance(value, datetime) else datetime.fromisoformat(value.replace('Z', '+00:00'))
    if result.tzinfo is None:
        raise ValueError('timestamps must include a timezone')
    return result.astimezone(timezone.utc)


def nonnegative(value):
    try:
        result = float(value)
        if not math.isfinite(result) or not 0 <= result <= 365000:
            raise ValueError()
        return result
    except (ValueError, OverflowError):
        raise argparse.ArgumentTypeError('must be a finite number between 0 and 365000') from None


def positive(value):
    result = nonnegative(value)
    if result == 0:
        raise argparse.ArgumentTypeError('must be greater than zero')
    return result


def metadata_arg(value):
    result = {}
    for item in value.split(','):
        key, sep, val = item.partition('=')
        if not sep or not key or key in result:
            raise argparse.ArgumentTypeError('use unique nonempty keys: key=value,key2=value2')
        result[key] = val
    return result


def identifier(value):
    if not isinstance(value, str) or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_-]*', value):
        raise BackendError(f'invalid resource ID: {value!r}')
    return value


def snapshot_identifier(value):
    # The API reports a named snapshot as "namespace/alias:tag" and an unnamed one as "templateID:tag".
    if not isinstance(value, str) or not re.fullmatch(r'[A-Za-z0-9_-]+(?:/[A-Za-z0-9_-]+)?(?::[A-Za-z0-9_.-]+)?', value):
        raise BackendError(f'invalid snapshot ID: {value!r}')
    return value


def normalize(raw):
    try:
        sid = raw.get('sandboxID') or raw.get('sandboxId')
        state, metadata = raw['state'], raw.get('metadata') or {}
        if state not in ('paused', 'running') or not isinstance(metadata, dict):
            raise ValueError('invalid state or metadata')
        return SimpleNamespace(sandbox_id=identifier(sid), state=state,
                               started_at=timestamp(raw['startedAt']),
                               end_at=timestamp(raw['endAt']), metadata=metadata)
    except (KeyError, AttributeError, TypeError, ValueError) as error:
        raise BackendError(f'invalid sandbox response: {error}') from error


class APIBackend:
    def __init__(self, rate=20, retries=5, page_size=100, timeout=60, client=None):
        key = os.environ.get('E2B_API_KEY')
        if not key:
            raise BackendError('E2B_API_KEY is required')
        base = os.environ.get('E2B_API_URL') or f"https://api.{os.environ.get('E2B_DOMAIN') or 'e2b.app'}"
        parsed = urlparse(base)
        if parsed.scheme not in ('http', 'https') or not parsed.netloc or parsed.username or parsed.password:
            raise BackendError('E2B_API_URL must be an HTTP(S) URL without embedded credentials')
        self.client = client or httpx.Client(base_url=base.rstrip('/'),
                                          headers={'X-API-Key': key}, timeout=timeout,
                                          follow_redirects=False)
        self.control = RequestControl(rate, retries)
        self.page_size = page_size
        self.invalid_rows = 0

    def close(self):
        self.client.close()

    def cancel(self):
        self.control.cancelled.set()

    def pages(self, path, params):
        params = {**params, 'limit': self.page_size}
        token = None
        while True:
            response = self.control.request(self.client, 'GET', path, params=params)
            try:
                page = response.json()
                if not isinstance(page, list):
                    raise ValueError('expected a list')
            except (ValueError, TypeError) as error:
                raise BackendError(f'{path}: invalid listing response') from error
            next_token = [REDACTED]'X-Next-Token')
            if next_token and next_token == token:
                raise BackendError(f'{path}: pagination cursor did not advance')
            yield page
            if not next_token:
                return
            token = next_token
            params['nextToken'] = token

    def list_paused(self, metadata=None):
        params = {'state': 'paused', 'order': 'asc'}
        if metadata:
            params['metadata'] = urlencode({quote(k): quote(v) for k, v in metadata.items()})
        for page in self.pages('/v2/sandboxes', params):
            for item in page:
                try:
                    info = normalize(item)
                except BackendError as error:
                    # One unreadable row must not abort a cron run; log it and keep streaming.
                    self.invalid_rows += 1
                    sid = (item.get('sandboxID') or item.get('sandboxId')) if isinstance(item, dict) else None
                    print(f'Skipped unreadable listing row {sid!r}: {error}', file=sys.stderr, flush=True)
                    continue
                yield info

    def get_info(self, sid):
        response = self.control.request(self.client, 'GET', f'/sandboxes/{identifier(sid)}')
        try:
            return normalize(response.json())
        except (ValueError, TypeError) as error:
            raise BackendError('invalid sandbox response') from error

    def kill(self, sid):
        try:
            self.control.request(self.client, 'DELETE', f'/sandboxes/{identifier(sid)}')
            return True
        except Missing:
            return False

    def snapshots(self, sid):
        ids = []
        for page in self.pages('/snapshots', {'sandboxID': identifier(sid)}):
            for item in page:
                if not isinstance(item, dict):
                    raise BackendError('invalid snapshot listing response')
                ids.append(snapshot_identifier(item.get('snapshotID') or item.get('snapshotId')))
        return list(dict.fromkeys(ids))

    def delete_snapshot(self, sid):
        try:
            self.control.request(self.client, 'DELETE', f'/templates/{quote(snapshot_identifier(sid), safe="")}')
            return True
        except Missing:
            return False


def backend(name='sdk', **kwargs):
    if os.environ.get('E2B_DEBUG', '').lower() == 'true':
        raise BackendError('E2B_DEBUG=true is unsupported; unset it before account operations')
    return APIBackend(**kwargs)

#!/usr/bin/env python3
"""Preview or delete old paused E2B sandboxes.

Named snapshots are separate resources, included only with --delete-snapshots.
Pages are consumed incrementally, and every HTTP attempt shares the request budget.
Deletion uses the listed state by default; --recheck adds a fresh lookup.
"""
import argparse
from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait
from itertools import islice
from datetime import datetime, timedelta, timezone
import sys

from cleanup_journal import Journal, run_lock
from sandbox_backend import AuthorizationError, BackendError, Missing, RetryLaterError, backend, metadata_arg, nonnegative, positive, timestamp


def parser_for_cli():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--days', type=nonnegative, default=90, help='age in days (default 90)')
    parser.add_argument('--metadata', type=metadata_arg, help='key=value,key2=value2')
    parser.add_argument('--age-from', choices=['paused','started'], default='paused')
    parser.add_argument('--delete-snapshots', action='store_true', help='also include all named snapshots from matching paused sandboxes, regardless of snapshot age')
    parser.add_argument('--apply', action='store_true', help='delete matches; default is a dry run')
    parser.add_argument('--resumes-stopped', action='store_true', help=argparse.SUPPRESS)
    parser.add_argument('--recheck', action='store_true', help='recheck state, age and metadata immediately before deletion')
    parser.add_argument('--rate', type=positive, default=20, help='combined GET and DELETE attempts per second, default 20; lower this for shared budgets')
    parser.add_argument('--concurrency', type=int, default=10, help='sandbox deletes in flight, default 10')
    parser.add_argument('--page-size', type=int, default=100, help='resources per list request, 1-100, default 100')
    parser.add_argument('--retries', type=int, default=5, help='retries per request after 429/5xx or transport errors, default 5')
    parser.add_argument('--limit', type=int, help='process at most N matching/pending sandboxes per run')
    parser.add_argument('--lock-file', help='local overlap lock; defaults to a credential/endpoint-specific file in the temporary directory')
    parser.add_argument('--journal', help='named snapshot recovery file (default: account/selection-specific file beside this script)')
    parser.add_argument('--retry-pending', action='store_true', help='only process existing journal entries; use the same selection options as the original run')
    parser.add_argument('--backend', choices=['sdk','cli'], default='sdk', help=argparse.SUPPRESS)
    return parser


def is_eligible(info, args, cutoff):
    age = info.end_at if args.age_from == 'paused' else info.started_at
    return (info.state == 'paused' and age < cutoff and
            all(info.metadata.get(k) == v for k, v in (args.metadata or {}).items()))


def selected_rows(args, api, cutoff):
    for info in api.list_paused(args.metadata):
        # Start-time order only supports early termination for start-based retention.
        if args.age_from == 'started' and info.started_at >= cutoff:
            return
        if is_eligible(info, args, cutoff):
            yield info


def report_invalid_rows(api):
    count = getattr(api, 'invalid_rows', 0)
    if count:
        print(f'Skipped {count} unreadable listing row(s); see earlier messages. Other sandboxes were processed.', file=sys.stderr, flush=True)
    return count


def run_sandboxes(args, api, cutoff):
    total = deleted = skipped = failed = 0

    def delete(info):
        sid = info.sandbox_id
        try:
            if args.recheck:
                info = api.get_info(sid)
                if not is_eligible(info, args, cutoff):
                    return 'skipped', sid, 'state, age or metadata changed'
            return ('deleted' if api.kill(sid) else 'skipped'), sid, ''
        except Missing:
            return 'skipped', sid, 'already gone'
        except (AuthorizationError, RetryLaterError):
            raise
        except BackendError as error:
            return 'failed', sid, str(error)

    def collect(future):
        nonlocal deleted, skipped, failed
        outcome, sid, detail = future.result()
        if outcome == 'deleted':
            deleted += 1
            print(f'Deleted paused sandbox {sid}', flush=True)
        elif outcome == 'failed':
            failed += 1
            print(f'Failed {sid}: {detail}', file=sys.stderr, flush=True)
        else:
            skipped += 1
            print(f'Skipped {sid}: {detail or "already gone"}', flush=True)

    pool = ThreadPoolExecutor(max_workers=args.concurrency) if args.apply else None
    pending = set()
    try:
        for info in islice(selected_rows(args, api, cutoff), args.limit):
            total += 1
            print(f'{info.sandbox_id}\tstarted={info.started_at.isoformat()}\tpaused={info.end_at.isoformat()}', flush=True)
            if pool:
                pending.add(pool.submit(delete, info))
                if len(pending) >= args.concurrency:
                    done, pending = wait(pending, return_when=FIRST_COMPLETED)
                    for future in done:
                        collect(future)
        for future in pending:
            collect(future)
    except BaseException:
        api.cancel()
        for future in pending:
            future.cancel()
        raise
    finally:
        if pool:
            pool.shutdown(wait=True, cancel_futures=True)
    if args.apply:
        print(f'Deleted {deleted} of {total} matching/pending paused sandbox(es); skipped {skipped}, failed {failed}.')
    else:
        print(f'Dry run: {total} paused sandbox(es) matched/pending. Re-run with --apply to delete.')
    return 1 if failed or report_invalid_rows(api) else 0


def run(args, api, cutoff):
    def eligible(info):
        return is_eligible(info, args, cutoff)

    if not args.delete_snapshots:
        return run_sandboxes(args, api, cutoff)

    scope = dict(days=float(args.days), age_from=args.age_from, metadata=args.metadata or {})
    with Journal(args.journal, scope, args.apply) as journal:
        # Load recovery records before listing so --retry-pending can work during list failures.
        pending = journal.pending if journal else {}
        recovering = set(pending)

        def entries():
            for sid in recovering:
                yield sid, None
            if not args.retry_pending:
                for info in selected_rows(args, api, cutoff):
                    if info.sandbox_id not in recovering:
                        yield info.sandbox_id, info

        total = 0
        deleted = skipped = failed = snapshots_deleted = 0
        if journal:
            print(f'Named snapshot recovery journal: {journal.path}')
        for sid, listed in islice(entries(), args.limit):
            total += 1
            record = pending.get(sid)
            if listed:
                print(f'{sid}\tstarted={listed.started_at.isoformat()}\tpaused={listed.end_at.isoformat()}')
            else:
                print(f'Pending cleanup for {sid}')
            try:
                if not args.apply:
                    if args.delete_snapshots:
                        snapshots = record['snapshots'] if record else api.snapshots(sid)
                        for snapshot in snapshots:
                            print(f'  named snapshot {snapshot}')
                    continue

                try:
                    current = api.get_info(sid)
                except Missing:
                    current = None
                if current is None and record is None:
                    print(f'Skipped {sid}: already gone')
                    skipped += 1
                    continue
                if current is not None:
                    unchanged = record is None or (current.started_at == timestamp(record['started_at']) and current.end_at == timestamp(record['paused_at']))
                    if not eligible(current) or not unchanged or (record and record['status'] == 'sandbox_deleted'):
                        print(f'Skipped {sid}: state, metadata, or pause changed')
                        skipped += 1
                        if record:
                            # Cancel snapshots of a parent whose eligibility changed; never delete them here.
                            del pending[sid]
                            journal.save()
                        continue
                    if args.delete_snapshots and record is None:
                        record = dict(status='prepared', started_at=current.started_at.isoformat(),
                                      paused_at=current.end_at.isoformat(), snapshots=api.snapshots(sid))
                        pending[sid] = record
                        journal.save()  # Must be durable before kill can run.
                    # Preserve the journaled parent identity across snapshot enumeration.
                    try:
                        latest = api.get_info(sid)
                    except Missing:
                        latest = None
                    if latest is not None and (not eligible(latest) or latest.started_at != current.started_at or latest.end_at != current.end_at):
                        print(f'Skipped {sid}: changed immediately before deletion')
                        skipped += 1
                        if record:
                            del pending[sid]
                            journal.save()
                        continue
                    if latest is not None and api.kill(sid):
                        deleted += 1
                        print(f'Deleted paused sandbox {sid}')
                    else:
                        skipped += 1
                        print(f'Paused sandbox {sid} already gone')
                else:
                    skipped += 1
                    print(f'Paused sandbox {sid} already gone; recovering named snapshot cleanup')
                if record:
                    record['status'] = 'sandbox_deleted'
                    journal.save()
                    for snapshot in list(record['snapshots']):
                        try:
                            if api.delete_snapshot(snapshot):
                                snapshots_deleted += 1
                                print(f'  Deleted named snapshot {snapshot}')
                            else:
                                print(f'  Named snapshot {snapshot} already gone')
                        except (AuthorizationError, RetryLaterError):
                            raise
                        except BackendError as error:
                            failed += 1
                            print(f'Failed named snapshot {snapshot}: {error}', file=sys.stderr)
                            continue
                        record['snapshots'].remove(snapshot)
                        journal.save()
                    if not record['snapshots']:
                        del pending[sid]
                        journal.save()
            except (AuthorizationError, RetryLaterError):
                raise
            except BackendError as error:
                failed += 1
                print(f'Failed {sid}: {error}', file=sys.stderr)
        if args.apply:
            print(f'Deleted {deleted} of {total} matching/pending paused sandbox(es); skipped {skipped}, failed {failed}.')
            if args.delete_snapshots:
                print(f'Deleted {snapshots_deleted} named snapshot(s); {len(pending)} pending sandbox record(s).')
        else:
            print(f'Dry run: {total} paused sandbox(es) matched/pending; failed {failed}. Re-run with --apply to delete.')
        return 1 if failed or report_invalid_rows(api) else 0


def main(argv=None):
    parser = parser_for_cli()
    args = parser.parse_args(argv)
    if args.retry_pending and not args.delete_snapshots:
        parser.error('--retry-pending requires --delete-snapshots')
    if not 1 <= args.page_size <= 100:
        parser.error('--page-size must be between 1 and 100')
    if not 1 <= args.concurrency <= 64:
        parser.error('--concurrency must be between 1 and 64')
    if not 0 <= args.retries <= 10:
        parser.error('--retries must be between 0 and 10')
    if args.limit is not None and args.limit < 1:
        parser.error('--limit must be at least 1')
    try:
        cutoff = datetime.now(timezone.utc) - timedelta(days=args.days)
        api = backend(args.backend, rate=args.rate, retries=args.retries, page_size=args.page_size)
        try:
            with run_lock(args.lock_file, args.apply):
                return run(args, api, cutoff)
        finally:
            api.close()
    except (BackendError, OSError, ValueError, KeyError, TypeError, ImportError) as error:
        print(f'Cleanup failed: {error}', file=sys.stderr)
        return 1


if __name__ == '__main__':
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        print('Interrupted; completed deletes stand. Re-run to continue.', file=sys.stderr)
        sys.exit(130)
